pub(super) fn fft(length: usize) -> Option<FftPlan> {
    let data = match length {
        60 => FFT_60,
        120 => FFT_120,
        240 => FFT_240,
        480 => FFT_480,
        _ => return None,
    };
    let stages = data
        .iter()
        .map(|&(size, radix, rows)| Stage {
            size,
            radix,
            twiddles: rows.to_vec(),
        })
        .collect();
    Some(FftPlan { length, stages })
}

pub(super) fn mdct(coefficients: usize, overlap: usize) -> Option<MdctPlan> {
    if overlap != 120 {
        return None;
    }
    let rows = match coefficients {
        120 => MDCT_120,
        240 => MDCT_240,
        480 => MDCT_480,
        960 => MDCT_960,
        _ => return None,
    };
    Some(MdctPlan {
        coefficients,
        rows: rows.to_vec(),
        fft: fft(coefficients / 2)?,
    })
}
